package client

// Golden differential tests for Phase 9 authentication primitives.
//
// Vectors: tests/vectors/auth.json, generated by tools/vectors/generate.py
// (v_auth) by EXECUTING the Python reference:
//   - utils.parse_phone             (splusthon/utils.py:916-923)
//   - password.compute_hash         (splusthon/password.py:113-118)
//   - password.compute_check        (splusthon/password.py:136-194)
//   - password.check_prime_and_good (splusthon/password.py:45-68)
//
// The SRP case records the reference's raw 256-byte `a` draw so this test
// replays the identical run through the Go implementation; byte equality
// of A and M1 is the differential contract.

import (
	"encoding/hex"
	"encoding/json"
	"os"
	"testing"

	"github.com/Skryldev/suromesh/tl/gen"
)

type authVectors struct {
	Meta struct {
		Generator string `json:"generator"`
		Seed      int64  `json:"seed"`
		Layer     int    `json:"layer"`
	} `json:"meta"`
	Cases []struct {
		ParsePhone []struct {
			Input  string `json:"input"`
			Valid  bool   `json:"valid"`
			Parsed string `json:"parsed"`
		} `json:"parse_phone"`
		PBKDF2 []struct {
			PasswordHash2 string `json:"password_hash2"`
			Salt          string `json:"salt"`
			Iterations    int    `json:"iterations"`
			DKLen         int    `json:"dklen"`
			DK            string `json:"dk"`
		} `json:"pbkdf2_sha512"`
		SRP struct {
			Salt1          string `json:"salt1"`
			Salt2          string `json:"salt2"`
			G              int32  `json:"g"`
			Password       string `json:"password"`
			SRPID          int64  `json:"srp_id"`
			SRPB           string `json:"srp_B"`
			X              string `json:"x"`
			ARaw           string `json:"a_raw"`
			ADrawCount     int    `json:"a_draw_count"`
			A              string `json:"A"`
			M1             string `json:"M1"`
			ServerVerified bool   `json:"server_verified"`
			SRPIDEcho      bool   `json:"srp_id_echo"`
		} `json:"srp"`
	} `json:"cases"`
}

func loadAuthVectors(t *testing.T) *authVectors {
	t.Helper()
	raw, err := os.ReadFile("../tests/vectors/auth.json")
	if err != nil {
		t.Fatalf("auth vectors: %v", err)
	}
	var v authVectors
	if err := json.Unmarshal(raw, &v); err != nil {
		t.Fatalf("auth vectors: %v", err)
	}
	return &v
}

func mustHex(t *testing.T, s string) []byte {
	t.Helper()
	b, err := hex.DecodeString(s)
	if err != nil {
		t.Fatalf("hex decode (%d chars): %v", len(s), err)
	}
	return b
}

// TestParsePhoneGolden: Go's ParsePhone must agree with the reference's
// utils.parse_phone on every vector (accept + value, or reject).
func TestParsePhoneGolden(t *testing.T) {
	v := loadAuthVectors(t)
	for _, c := range v.Cases {
		for _, p := range c.ParsePhone {
			got, err := ParsePhone(p.Input)
			if p.Valid {
				if err != nil {
					t.Errorf("parse_phone(%q): Go rejected (%v), reference accepted %q",
						p.Input, err, p.Parsed)
					continue
				}
				if got != p.Parsed {
					t.Errorf("parse_phone(%q) = %q, reference %q", p.Input, got, p.Parsed)
				}
			} else if err == nil {
				t.Errorf("parse_phone(%q) = %q, reference rejected", p.Input, got)
			}
		}
	}
}

// TestPBKDF2SHA512Golden pins the hand-rolled PBKDF2 (stdlib hmac/sha512)
// against the reference's hashlib.pbkdf2_hmac('sha512', ...) output.
func TestPBKDF2SHA512Golden(t *testing.T) {
	v := loadAuthVectors(t)
	for _, c := range v.Cases {
		for _, vec := range c.PBKDF2 {
			dk := pbkdf2SHA512(mustHex(t, vec.PasswordHash2), mustHex(t, vec.Salt),
				vec.Iterations, vec.DKLen)
			if got := hex.EncodeToString(dk); got != vec.DK {
				t.Fatalf("pbkdf2-sha512 mismatch:\n got %.32s\nwant %.32s", got, vec.DK)
			}
		}
	}
}

// TestSRPGolden is the core Phase 9 differential contract: with the
// reference's randomness pinned, the Go computeCheck must produce the
// byte-identical A and M1 that the Python reference produced.
func TestSRPGolden(t *testing.T) {
	v := loadAuthVectors(t)
	c := v.Cases[0].SRP

	if !c.ServerVerified {
		t.Fatal("vector generator reports server_verified=false; vector is invalid")
	}
	if c.ADrawCount != 1 {
		t.Fatalf("expected a single randomness draw in the vector, got %d", c.ADrawCount)
	}

	// x = int(compute_hash(...)) must match first (the KDF chain).
	gotX := hex.EncodeToString(srpComputeHash(mustHex(t, c.Salt1), mustHex(t, c.Salt2), c.Password))
	if gotX != c.X {
		t.Fatalf("compute_hash mismatch:\n got %s\nwant %s", gotX, c.X)
	}

	// Build the account.Password the reference compute_check consumed.
	srpID := c.SRPID
	pwd := &gen.AccountPassword{
		HasPassword: true,
		CurrentAlgo: &gen.PasswordKdfAlgoSHA256SHA256PBKDF2HMACSHA512iter100000SHA256ModPow{
			Salt1: mustHex(t, c.Salt1),
			Salt2: mustHex(t, c.Salt2),
			G:     c.G,
			P:     srpGoodPrime.Bytes(), // the standard prime (vector "p": "standard")
		},
		SRPB:  mustHex(t, c.SRPB),
		SRPID: &srpID,
	}

	// Replay the reference run with its exact `a` draw.
	pin := &pinnedRandom{data: mustHex(t, c.ARaw)}
	old := srpRandomSource
	srpRandomSource = pin
	defer func() { srpRandomSource = old }()

	srp, err := computeCheck(pwd, c.Password, srpPBKDF2Iterations)
	if err != nil {
		t.Fatalf("computeCheck: %v", err)
	}
	if got, want := hex.EncodeToString(srp.A), c.A; got != want {
		t.Fatalf("SRP A mismatch:\n got %.48s\nwant %.48s", got, want)
	}
	if got, want := hex.EncodeToString(srp.M1), c.M1; got != want {
		t.Fatalf("SRP M1 mismatch:\n got %s\nwant %s", got, want)
	}
	if srp.SRPID != c.SRPID {
		t.Fatalf("srp_id = %d, want %d", srp.SRPID, c.SRPID)
	}
}

// pinnedRandom replays a fixed byte stream (the reference's a draw).
type pinnedRandom struct{ data []byte }

func (p *pinnedRandom) Read(b []byte) (int, error) {
	n := copy(b, p.data)
	p.data = p.data[n:]
	return n, nil
}
